        zpracuj_zalozku ( nazev_zal, pocet_zapisu, kpi_pole ) { // sbaleni nebo robaleni zalozky
            var that = this;
            this.akt_tab = that.element.find("[data-param-id=" + nazev_zal + "]");
            that.akt_tab_opened = that.akt_tab.gtab("option", "opened")!;
            if (that.akt_tab_opened == true) {
                that.akt_tab.gtab("close");
                that.akt_tab[0].scrollIntoView(true);

                //kpi_pole.data.color = "black";
                //that.kpis!.update(); //update všech kpi
            }
            else {
                if (pocet_zapisu > 0) {
                    that.akt_tab.gtab("open");
                    that.akt_tab[0].scrollIntoView(true);

                    //kpi_pole.data.color = "blue";
                    //that.kpis!.update(); //update všech kpi

                }
            }
        }  

